select pod.purchase_order_id as id, pod.purchase_order_detail_id as purchaseDetailId, pod.purchase_org_name, pod.type as type, pod.code, pod.sku_id as skuId, pod.sku_no as skuNo, pod.product_name as productName, pod.plan_delivery_date as planDeliveryDate, pod.is_urgent as isUrgent, pod.delivery_warehouse_name as deliveryWarehouseName, pod.tax_price as taxPrice, pod.tax_rate as taxRate, pod.currency_symbol, pod.purchase_qty as purchaseQty, pod.purchase_amount as purchaseAmount, pod.remark, pod.purchase_user_name as purchaseUserName from purchase_order_detail pod
${params.sqlMap.default}
and pod.is_deleted = false
and pod.supplier_id = #{params.supplierId}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pod.purchase_order_id desc,pod.purchase_order_detail_id asc

select pod.purchase_order_id as id, pod.purchase_order_detail_id as purchaseDetailId, pod.purchase_org_name, pod.type as type, pod.code, pod.sku_id as skuId, pod.sku_no as skuNo, pod.product_name as productName, pod.plan_delivery_date as planDeliveryDate, case when pod.plan_delivery_date is not null then date_part('day', pod.plan_delivery_date::timestamp - CURRENT_DATE::timestamp) else null end AS deliveryCycle, pod.is_urgent as isUrgent, pod.delivery_warehouse_name as deliveryWarehouseName, pod.tax_price as taxPrice, pod.tax_rate as taxRate, pod.currency_symbol, pod.purchase_qty as purchaseQty, pod.purchase_amount as purchaseAmount, pod.remark, pod.purchase_user_name as purchaseUserName from purchase_order_detail pod
${params.sqlMap.default}
and pod.is_deleted = false
and pod.supplier_id = #{params.supplierId}
${params.permissionSql}
